static QPoint pointOnPage(PDFDocumentWindow *window,const QPointF &point){auto *scene=qobject_cast<QtPDF::PDFDocumentScene*>(window->widget()->scene());if(!scene)return {};auto *page=qgraphicsitem_cast<QtPDF::PDFPageGraphicsItem*>(scene->pageAt(0));if(!page)return {};const auto backend=page->page().toStrongRef();if(!backend)return {};return window->widget()->mapFromScene(page->mapToScene(page->mapFromPage(QPointF(point.x(),backend->pageSizeF().height()-point.y()))));}
static void selectText(PDFDocumentWindow *window,const QPoint &first,const QPoint &last,bool reverse=false){auto *viewport=window->widget()->viewport();auto send=[&](QEvent::Type type,QPoint point,Qt::MouseButton button,Qt::MouseButtons buttons){QMouseEvent event(type,QPointF(point),QPointF(viewport->mapToGlobal(point)),button,buttons,Qt::NoModifier);QApplication::sendEvent(viewport,&event);};const auto a=reverse?last:first,b=reverse?first:last;send(QEvent::MouseButtonPress,a,Qt::LeftButton,Qt::LeftButton);for(int i=1;i<=10;++i){const auto point=a+(b-a)*i/10;if(selectionRecording)selectionRecording->pointer=viewport->mapToGlobal(point);send(QEvent::MouseMove,point,Qt::NoButton,Qt::LeftButton);if(selectionRecording)settle(40);}send(QEvent::MouseButtonRelease,b,Qt::LeftButton,Qt::NoButton);settle(50);}
