 auto *viewer=new PDFDocumentWindow(pdf);viewer->resize(720,760);viewer->show();viewer->widget()->setMouseModeSelect();settle(300);viewer->showNormal();viewer->resize(720,760);viewer->widget()->zoomFitWidth();viewer->widget()->horizontalScrollBar()->setValue(viewer->widget()->horizontalScrollBar()->minimum());viewer->widget()->verticalScrollBar()->setValue(viewer->widget()->verticalScrollBar()->minimum());settle(500);Recording recording;if(qEnvironmentVariableIsSet("TEXLINE_INTUITIVE_RECORD")){recording.start(folder+"/actual-flow",viewer);selectionRecording=&recording;}auto doc=viewer->widget()->document().toStrongRef();check("independent two-column PDF loads",doc&&doc->numPages()==1);if(!doc){app.exit(1);return;}
 auto search=[&](const QString &text){const auto found=doc->search(text,QtPDF::Backend::Search_CaseInsensitive);return found.isEmpty()?QRectF():found.first().bbox;};const auto first=search("LEFT_ONE"),last=search("LEFT_THREE");check("real rendered text positions found",!first.isEmpty()&&!last.isEmpty());
